-- 0043_nitya_karma_placeholders.sql
--
-- GENERATED by scripts/build-nitya-karma-placeholders.mjs. Do not hand-edit.
--
-- Puts the four nitya karmas from the Giri Sandhyavandanam on the shelf before
-- they are written, and adds the status column that lets the catalogue say so.
--
-- WHY status RATHER THAN JUST WAITING. A section with one card in it implies
-- there is one daily rite, which is false. Listing what is coming is honest and
-- costs nothing, because a planned card is not a link.
--
-- The alternative -- inserting them as ordinary poojas with no steps -- would
-- put four live links in the catalogue leading to a viewer with nothing in it.
-- It would not even error: it would render a preparation screen and a Start
-- button for a rite that does not exist. status is the difference between
-- "not yet" and "broken".
--
-- Sandhyavandanam is listed as planned too, although it is being transcribed
-- now. Until its steps land it is in the same state as the other three and
-- should not claim otherwise. A later migration flips it.
--
-- rule_type stays null: these are nitya, performed every day, and 0002 makes
-- the column nullable for exactly that. Same reasoning as 0037.
-- =============================================================================

begin;

alter table public.poojas
  add column if not exists status text not null default 'published';

do $$ begin
  alter table public.poojas
    add constraint poojas_status_ck check (status in ('published', 'planned'));
exception when duplicate_object or duplicate_table then null; end $$;

comment on column public.poojas.status is
  '''planned'' means the rite is listed in the catalogue but has no steps yet and must not be opened. The catalogue renders it as a card rather than a link. ''published'' is the default so every existing pooja keeps working.';

-- Agni, for Samidaadhaanam. Surya is already there.
--
-- All five of name_en, name_deva, name_ta, name_dative_deva and class are NOT
-- NULL, so the row is supplied whole. An insert naming only name_en parses and
-- then fails at run time, taking the migration with it.
--
-- The dative is the form every upachara line substitutes into, so it is stored
-- rather than derived: agni is an i-stem and its dative is agnaye, not the
-- aaya every other deity in this table takes.
insert into public.deities
  (id, name_en, name_deva, name_ta, name_dative_deva, class)
values ('agni', 'Agni', 'अग्नि', 'அக்னி', 'श्री अग्नये', 'god')
  on conflict (id) do nothing;

