   ritual_class, deity_id, duration_mins, eligibility, status, source_ref)
values
  ('sandhyavandanam', 'Sandhyavandanam', 'ஸந்த்யாவந்தனம்',
   'The daily worship of the junctures, performed at dawn, noon and dusk. Gayatri is invoked, japa is done and the sun is worshipped at its own three hours. Yajur Veda recension.',
   'தினமும் காலை, உச்சி, மாலை என மூன்று சந்தி வேளைகளிலும் செய்யப்படும் வழிபாடு. காயத்ரி ஆவாஹனம், ஜபம், சூர்ய உபஸ்தானம் ஆகியவை அடங்கியது.',
   'nitya', 'surya', 15, 'all', 'planned',
   'Yajurveda Trikaala Sandhyaavandanam, Giri Trading Agency, English translation by A. R. Parthasarathi. Placeholder: listed, not yet transcribed.')
on conflict (id) do update set
       title_ta       = excluded.title_ta,
       description_en = excluded.description_en,
       description_ta = excluded.description_ta,
       ritual_class   = excluded.ritual_class,
       updated_at     = now();

