-- --- assert ------------------------------------------------------------------
do $$
declare n int;
begin
  -- The column exists and every pooja that came before it is unaffected.
  select count(*) into n from information_schema.columns
   where table_schema = 'public' and table_name = 'poojas' and column_name = 'status';
  if n <> 1 then raise exception 'status column is missing'; end if;

  select count(*) into n from public.poojas
   where id in ('ganesha_standard', 'varalakshmi_vratham', 'nitya_panchayatana')
     and status <> 'published';
  if n <> 0 then raise exception '% existing pooja(s) were knocked off published', n; end if;

  -- All four are listed, all four are planned.
  select count(*) into n from public.poojas
   where id in ('sandhyavandanam', 'samidadhanam', 'brahma_yajnam', 'bhojana_vidhi') and status = 'planned'
     and ritual_class = 'nitya';
  if n <> 4 then raise exception 'expected 4 planned nitya karmas, found %', n; end if;

  -- And none of them has steps, which is what planned MEANS. If one does, the
  -- catalogue is hiding a rite that is ready.
  select count(*) into n from public.pooja_steps s
    join public.poojas p on p.id = s.pooja_id
   where p.status = 'planned';
  if n > 0 then raise exception '% step(s) belong to a pooja still marked planned', n; end if;

  -- The constraint bites. Checked by trying it, not by reading it.
  begin
    update public.poojas set status = 'soon' where id = 'sandhyavandanam';
    raise exception 'the status check constraint let an invalid value through';
  exception when check_violation then null;
  end;
end $$;


-- Carriage returns, from pasting this file into a browser SQL editor. See
-- scripts/_migration.mjs.
do $$
declare
  r record;
  n bigint;
begin
  for r in
    select c.table_name, c.column_name
      from information_schema.columns c
      join information_schema.tables t
        on t.table_schema = c.table_schema and t.table_name = c.table_name
     where c.table_schema = 'public'
       and t.table_type = 'BASE TABLE'
       and c.data_type in ('text', 'character varying', 'character')
  loop
    execute format(
      'update public.%I set %I = replace(%I, chr(13), %L)'
      || ' where position(chr(13) in %I) > 0',
      r.table_name, r.column_name, r.column_name, '', r.column_name
    );
    get diagnostics n = row_count;
    if n > 0 then
      raise notice 'stripped CR from % row(s) of %.%', n, r.table_name, r.column_name;
    end if;
  end loop;
end $$;

commit;
